begin;
create table public.arena_alliance_posts(id bigint generated always as identity primary key,alliance_id uuid not null references public.arena_alliances(id)on delete cascade,author_id uuid references public.profiles(id)on delete set null,kind text not null default'post'check(kind in('post','announcement')),body text not null check(length(trim(body))between 1 and 1000),pinned boolean not null default false,deleted_at timestamptz,created_at timestamptz not null default now());
create table public.arena_alliance_post_comments(id bigint generated always as identity primary key,post_id bigint not null references public.arena_alliance_posts(id)on delete cascade,author_id uuid references public.profiles(id)on delete set null,body text not null check(length(trim(body))between 1 and 500),deleted_at timestamptz,created_at timestamptz not null default now());
create table public.arena_alliance_post_reactions(post_id bigint not null references public.arena_alliance_posts(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,emoji text not null check(emoji in('amen','fire','heart','pray')),created_at timestamptz not null default now(),primary key(post_id,user_id,emoji));
create index arena_alliance_posts_feed on public.arena_alliance_posts(alliance_id,pinned desc,id desc)where deleted_at is null;create index arena_alliance_comments_post on public.arena_alliance_post_comments(post_id,id)where deleted_at is null;
alter table public.arena_alliance_posts enable row level security;alter table public.arena_alliance_posts force row level security;alter table public.arena_alliance_post_comments enable row level security;alter table public.arena_alliance_post_comments force row level security;alter table public.arena_alliance_post_reactions enable row level security;alter table public.arena_alliance_post_reactions force row level security;revoke all on public.arena_alliance_posts,public.arena_alliance_post_comments,public.arena_alliance_post_reactions from anon,authenticated;
create or replace function public.arena_get_alliance_wall(p_before_id bigint default null,p_limit integer default 10)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;return jsonb_build_object('can_moderate',v_role in('founder','elder'),'posts',(select coalesce(jsonb_agg(to_jsonb(x)order by pinned desc,id desc),'[]'::jsonb)from(select p.id,p.kind,p.body,p.pinned,p.created_at,p.author_id,coalesce(a.display_name,'Guardião')author_name,a.avatar_url,(select coalesce(jsonb_object_agg(emoji,total),'{}'::jsonb)from(select emoji,count(*)total from public.arena_alliance_post_reactions where post_id=p.id group by emoji)r)reactions,(select coalesce(jsonb_agg(emoji),'[]'::jsonb)from public.arena_alliance_post_reactions where post_id=p.id and user_id=v_user)my_reactions,(select coalesce(jsonb_agg(to_jsonb(c)order by id),'[]'::jsonb)from(select c.id,c.body,c.created_at,c.author_id,coalesce(cp.display_name,'Guardião')author_name from public.arena_alliance_post_comments c left join public.profiles cp on cp.id=c.author_id where c.post_id=p.id and c.deleted_at is null order by c.id desc limit 20)c)comments from public.arena_alliance_posts p left join public.profiles a on a.id=p.author_id where p.alliance_id=v_alliance and p.deleted_at is null and(p_before_id is null or p.id<p_before_id)order by p.pinned desc,p.id desc limit least(greatest(p_limit,1),20))x));end;$$;
create or replace function public.arena_create_alliance_post(p_body text,p_kind text default'post')returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_id bigint;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;if p_kind not in('post','announcement')or(p_kind='announcement'and v_role not in('founder','elder'))then raise exception'invalid post kind';end if;if exists(select 1 from public.arena_alliance_posts where author_id=v_user and created_at>now()-interval'15 seconds')then raise exception'rate limited';end if;insert into public.arena_alliance_posts(alliance_id,author_id,kind,body)values(v_alliance,v_user,p_kind,trim(p_body))returning id into v_id;return v_id;end;$$;
create or replace function public.arena_comment_alliance_post(p_post_id bigint,p_body text)returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_id bigint;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if not exists(select 1 from public.arena_alliance_posts where id=p_post_id and alliance_id=v_alliance and deleted_at is null)then raise exception'post unavailable';end if;if exists(select 1 from public.arena_alliance_post_comments where author_id=v_user and created_at>now()-interval'5 seconds')then raise exception'rate limited';end if;insert into public.arena_alliance_post_comments(post_id,author_id,body)values(p_post_id,v_user,trim(p_body))returning id into v_id;return v_id;end;$$;
create or replace function public.arena_toggle_alliance_post_reaction(p_post_id bigint,p_emoji text)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_removed integer;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if p_emoji not in('amen','fire','heart','pray')or not exists(select 1 from public.arena_alliance_posts where id=p_post_id and alliance_id=v_alliance and deleted_at is null)then raise exception'invalid reaction';end if;delete from public.arena_alliance_post_reactions where post_id=p_post_id and user_id=v_user and emoji=p_emoji;get diagnostics v_removed=row_count;if v_removed=0 then insert into public.arena_alliance_post_reactions values(p_post_id,v_user,p_emoji,now());end if;return jsonb_build_object('active',v_removed=0);end;$$;
create or replace function public.arena_moderate_alliance_post(p_post_id bigint,p_action text)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_author uuid;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;select author_id into v_author from public.arena_alliance_posts where id=p_post_id and alliance_id=v_alliance and deleted_at is null;if v_author is null then raise exception'post unavailable';end if;if p_action='delete'and(v_author=v_user or v_role in('founder','elder'))then update public.arena_alliance_posts set deleted_at=now()where id=p_post_id;elsif p_action in('pin','unpin')and v_role in('founder','elder')then update public.arena_alliance_posts set pinned=p_action='pin'where id=p_post_id;else raise exception'permission denied';end if;return jsonb_build_object('updated',true,'action',p_action);end;$$;
revoke all on function public.arena_get_alliance_wall(bigint,integer),public.arena_create_alliance_post(text,text),public.arena_comment_alliance_post(bigint,text),public.arena_toggle_alliance_post_reaction(bigint,text),public.arena_moderate_alliance_post(bigint,text)from public;grant execute on function public.arena_get_alliance_wall(bigint,integer),public.arena_create_alliance_post(text,text),public.arena_comment_alliance_post(bigint,text),public.arena_toggle_alliance_post_reaction(bigint,text),public.arena_moderate_alliance_post(bigint,text)to authenticated;
commit;
